import ast,datetime,hashlib,json,pathlib,urllib.parse,xml.etree.ElementTree as ET
R=pathlib.Path(__file__).resolve().parent
S=R.parent/'author-source'/'zhuziguang__GS-DTA'/'source'
manifest=json.loads((S.parent/'manifest.json').read_text(encoding='utf-8'))
primary=json.loads((R/'primary-receipt.json').read_text(encoding='utf-8'))
meta=json.loads((R/'official-PMC-metadata.json').read_text(encoding='utf-8'))
xml=ET.fromstring((R/'official-fulltext.xml').read_bytes())
pdftext=(R/'GS-DTA-published.txt').read_text(encoding='utf-8')
assert primary['doi'].lower() in pdftext.lower()
expected_md5=urllib.parse.parse_qs(urllib.parse.urlparse(meta['pdf_url']).query)['md5'][0]
assert expected_md5==primary['pdf_md5']
assert meta['is_manuscript'] is False
verified=[]
for f in manifest['files']:
 b=pathlib.Path(f['local']).read_bytes();assert hashlib.sha256(b).hexdigest()==f['sha256']
 if f['local'].endswith('.py'):ast.parse(b.decode('utf-8-sig'))
 verified.append(f['path'])
dates=[{'type':e.attrib,'text':'-'.join(''.join(c.itertext()) for c in e)} for e in xml.findall('.//article-meta/pub-date')]
evidence=[]
for rel in ['Models/gatv2_gcn.py','create_data.py','training.py','training_validation.py']:
 for n,line in enumerate((S/rel).read_text(encoding='utf-8-sig').splitlines(),1):
  if any(t in line for t in ['class GAT','self.gat','self.gcn','self.fc_g','self.conv_xt','self.embedding_xt','self.lstm_xt','transformer_layer','permute(','mean(dim=0)','return out','def atom_features','max_seq_len =','modeling =','from models.','TRAIN_BATCH_SIZE','LR =','NUM_EPOCHS']):evidence.append({'path':str(S/rel),'line':n,'text':line.strip()})
